(72, 'Telephone ngendanwa ntigomba gukoreshwa:', 'Ahari ibimenyetso bimurika', 'Igihe utwaye ikinyabiziga Ku muvuduko wa 20km/h', 'A na B ni ibisubizo by’ukuri', 'Nta gisubizo cy’ukuri', 'D', NULL),
