(1, 'erneste', '+250789245524', 17, 20, '{\"question_1\":\"B\",\"question_3\":\"A\",\"question_5\":\"D\",\"question_10\":\"D\",\"question_14\":\"D\",\"question_16\":\"C\",\"question_19\":\"D\",\"question_24\":\"C\",\"question_41\":\"A\",\"question_48\":\"B\",\"question_54\":\"C\",\"question_58\":\"D\",\"question_60\":\"C\",\"question_61\":\"C\",\"question_68\":\"B\",\"question_71\":\"D\",\"question_79\":\"D\",\"question_81\":\"B\",\"question_85\":\"C\",\"question_91\":\"A\"}', '[{\"id\":1,\"correct_option\":\"B\",\"question\":\"Mu gihe utwaye ikinyabiziga uva kuri A ugana kuri B, Iki kimenyetso kiri mu muhanda kivuze iki ?\\r\\n\",\"option_a\":\"Umuyobozi w’ikinyabiziga ashobora kunyuranaho arenze umurongo wera udacagaguye\",\"option_b\":\"Umuyobozi w’ikinyabiziga abujijwe kunyuranaho arenze imirongo yera\",\"option_c\":\"Umuyobozi w’ikinyabiziga yemerewe kunyuranaho\",\"option_d\":\"Abayobozi b’ibinyamitende gusa bemerewe kunyuranaho barenze umurongo wera udacagaguye\",\"image_path\":\"sign5.png\"},{\"id\":2,\"correct_option\":\"A\",\"question\":\"Ikinyabiziga cyose cyangwa ibinyabiziga\\r\\nbigenda bigomba kugira:\",\"option_a\":\"Umuyobozi\",\"option_b\":\"Umuherekeza\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":3,\"correct_option\":\"C\",\"question\":\"Ijambo “akayira” bivuga inzira\\r\\nnyabagendwa ifunganye yagenewe gusa:\",\"option_a\":\"Abanyamaguru\",\"option_b\":\"Ibinyabiziga bigendera ku biziga bibiri\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":4,\"correct_option\":\"C\",\"question\":\"Umurongo uciyemo uduce umenyesha\\r\\nahegereye umurongo ushobora kuzuzwa\\r\\nn’uturanga gukata tw’ibara ryera utwo\\r\\nturanga cyerekezo tumenyesha :\",\"option_a\":\"Igisate cy’umuhanda abayobozi bagomba gukurikira\",\"option_b\":\"Ahegereye umurongo ukomeje\",\"option_c\":\"Igabanurwa ry’umubare w’ibisate by’umuha